@pytest.mark.smoke
def test_get_workflow_runs_smoke_success(
    require_auth,
    api_client,
    config_test_data: Dict[str, Any],
    endpoint_test_data: List[Dict[str, Any]],
    swagger_spec_validator: SwaggerSchemaValidator,
    endpoint_path_template: str,
):
    """
    Smoke: Successful workflow runs retrieval using only REQUIRED path parameters.
    Iterates through all scenarios but sends only required parameters.
    """
    for idx, scenario in enumerate(endpoint_test_data):
        merged = _merge_test_data(config_test_data, scenario)
        # Required path parameters must come from config_test_data or scenario JSON
        project_slug = merged.get("project-slug")
        workflow_name = merged.get("workflow-name")
        if not project_slug or not workflow_name:
            pytest.skip(f"Missing required path parameter(s) for scenario index {idx}")

        endpoint_path = _format_endpoint_path(project_slug, workflow_name)

        # No optional query params for smoke
        params = _build_query_params(merged, include_optionals=False)

        # Execute request
        resp: Response = api_client.get(endpoint_path, params=params)

        # Assert status code as given by scenario (do not hardcode)
        expected_status = merged.get("statusCode")
        if expected_status is None:
            pytest.skip(f"No expected statusCode provided in scenario index {idx}")
        assert resp.status_code == expected_status, f"Unexpected status code for scenario index {idx}: {resp.status_code} != {expected_status}"

        # Validate response schema using the provided validator
        key = _response_schema_key(resp.status_code)
        validation = swagger_spec_validator.validate_schema_by_response(
            endpoint_path_template, "GET", key, resp
        )
        assert validation.get("valid") is True, f"Schema validation failed (smoke, idx={idx}): {validation}"


